import assert from 'node:assert/strict'
const base = 'http://localhost:3017'
for (const [path, name, price, related] of [
  ['/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40', 'Stone vase'],
  ['/products/lamp?currency=USD', 'Brass lamp', 'USD 120.00', 'Stone vase'],
  ['/products/vase?currency=EUR', 'Stone vase', 'EUR 73.60', 'Brass lamp'],
  ['/products/lamp', 'Brass lamp', 'USD 120.00', 'Stone vase'],
  ['/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40', 'Stone vase'],
]) {
  const response = await fetch(base + path)
  const chunks = []
  const start = performance.now()
  for await (const chunk of response.body) chunks.push({ at: Math.round(performance.now() - start), text: new TextDecoder().decode(chunk) })
  const html = chunks.map(({ text }) => text).join('')
  assert.equal(response.status, 200, path)
  for (const text of ['Signal Shop collection', name, price, 'Related products', related]) assert.ok(html.includes(text), `${path}: missing ${text}`)
  const first = chunks[0].text
  assert.ok(first.includes('Loading product details...'), `${path}: shell missing product fallback`)
  assert.ok(first.includes('Signal Shop collection'), `${path}: shell missing shop frame`)
  const productIndex = chunks.findIndex(({ text }) => text.includes(price))
  const relatedIndex = chunks.findIndex(({ text }) => text.includes(related))
  console.log(`${path}: ${response.status}, ${chunks.length} chunks, shell=${chunks[0].at}ms, product=${chunks[productIndex]?.at}ms, related=${chunks[relatedIndex]?.at}ms`)
}
